function formatReal(?float $value, int $decimals = 4): string
{
    if ($value === null) {
        return '-';
    }
    $text = number_format($value, $decimals, '.', '');
    return (float) $text == 0.0 ? number_format(0.0, $decimals, '.', '') : $text;
}
